18	func newTestHandler(t *testing.T) (http.Handler, *app.App) {
19		t.Helper()
20		s, err := app.Open(filepath.Join(t.TempDir(), "test.db"))
21		if err != nil {
22			t.Fatal(err)
23		}
24		t.Cleanup(func() { _ = s.Close() })
25		return NewHandler(s), s
26	}
27	
28	func postJSON(t *testing.T, h http.Handler, url string, body any) (*httptest.ResponseRecorder, map[string]any) {
29		t.Helper()
30		var r *http.Request
31		switch b := body.(type) {
32		case string:
33			r = httptest.NewRequest(http.MethodPost, url, strings.NewReader(b))
34		case []byte:
35			r = httptest.NewRequest(http.MethodPost, url, bytes.NewReader(b))
